1	// Shared plumbing for this pack's checks.
2	//
3	// Deliberately dependency-free: a local pack's check modules must load even when
4	// the gitignored canon mount is absent (the project's own vitest run is exactly
5	// that situation), so nothing here imports `engine/checks/helpers/*`. The two
6	// things every rule needs are a finding constructor and a comment stripper.
7	
8	/** The plain finding object the checks runner consumes (engine/checks/README.md). */
9	export function finding(rule, { file, line = null, what, fix, why = null, severity = null }) {
10	  return {
11	    rule: rule.id,
12	    severity: severity || rule.severity,
13	    file,
14	    line,
15	    what,
16	    why: why || rule.why,
17	    fix,
18	    doc: rule.doc,
19	  };
20	}
21	
22	// String-aware comment stripper. Every rule below matches against source *code*:
23	// a comment that merely names `chrome.tts.speak` or `getUserMedia` describes the
24	// trap, it doesn't spring it — and this pack's own prose would otherwise fire its
25	// own checks. Same technique the repo's arch test already uses
26	// (extension-test/unit/arch.test.js), kept here so the pack stands alone.
27	// Newlines are preserved so line numbers survive the strip.
28	export function stripComments(source) {
29	  let out = '';
30	  let state = 'code'; // code | line | block | sq | dq | tpl
31	  for (let i = 0; i < source.length; i++) {
32	    const c = source[i];
33	    const c2 = source[i + 1];
34	    if (state === 'code') {
35	      if (c === '/' && c2 === '/') { state = 'line'; i++; continue; }
36	      if (c === '/' && c2 === '*') { state = 'block'; i++; continue; }
37	      if (c === "'") state = 'sq';
38	      else if (c === '"') state = 'dq';
39	      else if (c === '`') state = 'tpl';
40	      out += c;
41	    } else if (state === 'line') {
42	      if (c === '\n') { state = 'code'; out += c; }
43	    } else if (state === 'block') {
44	      if (c === '*' && c2 === '/') { state = 'code'; i++; }
45	      else if (c === '\n') out += c;
46	    } else {
47	      out += c;
48	      if (c === '\\') { out += c2 ?? ''; i++; }
49	      else if ((state === 'sq' && c === "'") || (state === 'dq' && c === '"') || (state === 'tpl' && c === '`')) {
50	        state = 'code';
51	      }
52	    }
53	  }
54	  return out;
55	}
56	
57	// What counts as shipped browser source. Deliberately NOT a hard-coded project
58	// root: every rule in this pack is gated on the speech API it judges actually
59	// appearing in the file, so the trigger is the API usage itself and the scan can
60	// safely be repo-shaped. A path scope hard-wired to one project's layout would
61	// make all three rules match zero files — and pass VACUOUSLY GREEN — in any repo
62	// laid out differently, which is the worst failure mode a check has.
63	//
64	// The one thing the scan must still exclude is test scaffolding: hand-rolled
65	// speech fakes implement only the halves of a contract a given case exercises,
66	// and holding purpose-built scaffolding to the production contract is a false
67	// alarm. That exclusion is expressed directly — by test/vendor path and test
68	// filename — instead of being a side effect of the source root.
69	const SOURCE_EXT = /\.(?:m|c)?[jt]sx?$/;
70	const NOT_SOURCE = [
71	  /(?:^|\/)(?:node_modules|dist|build|out|coverage|vendor|third_party)\//,
72	  /(?:^|\/)(?:tests?|__tests__|__mocks__|spec|fixtures?|mocks?|e2e)\//,
73	  /(?:^|[./-])(?:test|spec|fixture|mock|stub|fake)s?\.[^/]+$/,
74	];
75	export const isSource = (file) => SOURCE_EXT.test(file) && !NOT_SOURCE.some((re) => re.test(file));
76	
77	/** 1-based line number of `index` in `text`. */
78	export const lineOf = (text, index) => text.slice(0, index).split('\n').length;
79	
80	/**
81	 * Both legal ways to wire a speech event, as one matcher: the `onfoo =` property
82	 * assignment and `addEventListener('foo', …)`. The DOM offers both for every one
83	 * of these targets and neither is more correct, so a rule that knows only the
84	 * property form silently passes half the world's code — and false-alarms on a
85	 * file that mixes the two (`rec.onresult = …` beside
86	 * `rec.addEventListener('error', …)` reads as "no error handler" to a matcher
87	 * that only understands `.onerror =`).
88	 */
89	export const wires = (src, event) =>
90	  new RegExp(
91	    `\\.\\s*on${event}\\s*=|addEventListener\\s*\\(\\s*['"\`]${event}['"\`]`,
92	  ).test(src);
93	
94	/** Does `text` contain `name` as a string literal? */
95	export const quoted = (text, name) => new RegExp(`['"\`]${name}['"\`]`).test(text);
96	
97	/**
98	 * The balanced bracketed run beginning at the opener at `open` (inclusive of both
99	 * brackets), or null when the source is unbalanced — a half-written file should
100	 * make a check say nothing, never guess. String and template literals are skipped
101	 * so a bracket inside "a(b)" can't be read as syntax.
102	 */
103	export function balanced(src, open) {
104	  let depth = 0;
105	  for (let i = open; i < src.length; i++) {
106	    const c = src[i];
107	    if (c === '"' || c === "'" || c === '`') {
108	      const quote = c;
109	      for (i += 1; i < src.length; i++) {
110	        if (src[i] === '\\') { i += 1; continue; }
111	        if (src[i] === quote) break;
112	      }
113	      continue;
114	    }
115	    if (c === '{' || c === '[' || c === '(') depth += 1;
116	    else if (c === '}' || c === ']' || c === ')') {
117	      depth -= 1;
118	      if (depth === 0) return src.slice(open, i + 1);
119	    }
120	  }
121	  return null;
122	}
123

1	import { finding, stripComments, isSource, lineOf, balanced } from './lib.mjs';
2	
3	// `suppressLocalAudioPlayback` and `restrictOwnAudio` are `getDisplayMedia`
4	// SCREEN-CAPTURE constraints. They filter the playout of a captured tab out of
5	// that tab's audio track; they say nothing about a microphone, and getUserMedia
6	// ignores them entirely — no throw, no warning, no `OverconstrainedError`.
7	//
8	// They are reached for by name: someone hunting the app's own TTS leaking back
9	// through the mic reads "suppress local audio playback" / "restrict own audio"
10	// as exactly the fix, sets it on the mic capture, and ships believing self-echo
11	// is handled at the capture layer. It isn't, and the code that would have
12	// handled it (an application-level echo guard) never gets written. That is the
13	// silent-failure shape this whole pack is about: nothing throws, nothing logs,
14	// the feature simply doesn't exist.
15	//
16	// PARSED, NOT GREPPED. The names are only wrong where they reach a microphone
17	// capture, so the scan is the balanced argument list of a `getUserMedia(` call —
18	// plus, one hop, the initializer of any same-file constant that argument list
19	// references, since hoisting the constraints into a frozen constant is the
20	// ordinary way to write this:
21	//
22	//     const AUDIO = Object.freeze({ echoCancellation: true });
23	//     await media.getUserMedia({ audio: AUDIO });
24	//
25	// Everything outside that reach stays quiet on purpose — a file's real
26	// getDisplayMedia call, a `getSupportedConstraints()` probe, a screen-capture
27	// module's own constants table are all legitimate uses of these names, and a
28	// rule that grepped the file would false-alarm on every one of them. Comments
29	// are stripped first, so the paragraphs above cannot fire the rule.
30	
31	const CALL = /\bgetUserMedia\s*\(/g;
32	const DECL = /\b(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=/g;
33	const OPENER = /^\s*(?:[A-Za-z_$][\w$.]*\s*)?([[{(])/;
34	const DISPLAY_ONLY = ['suppressLocalAudioPlayback', 'restrictOwnAudio'];
35	
36	/**
37	 * The index ranges of `src` that a getUserMedia call's constraints actually
38	 * reach: the argument list itself, plus the initializer of every same-file
39	 * `const`/`let`/`var` the argument list names. One hop only — resolving further
40	 * needs real data-flow analysis, and a check that guesses is worse than one that
41	 * asks a simple, honest question.
42	 */
43	function reach(src, argsStart, args) {
44	  const regions = [{ start: argsStart, end: argsStart + args.length }];
45	  DECL.lastIndex = 0;
46	  for (let d = DECL.exec(src); d; d = DECL.exec(src)) {
47	    if (!new RegExp(`\\b${d[1]}\\b`).test(args)) continue;
48	    const eq = d.index + d[0].length;
49	    const head = OPENER.exec(src.slice(eq));
50	    if (!head) continue;
51	    const open = eq + head[0].length - 1;
52	    const init = balanced(src, open);
53	    if (init === null) continue;
54	    regions.push({ start: open, end: open + init.length });
55	  }
56	  return regions;
57	}
58	
59	const rule = {
60	  id: 'mic-constraints-not-screen-capture',
61	  severity: 'blocking',
62	  description: 'A microphone capture never asks for getDisplayMedia-only constraints',
63	  doc: '.claudinite/local/packs/browser-speech/RULES.md',
64	  why: 'suppressLocalAudioPlayback and restrictOwnAudio are getDisplayMedia screen-capture constraints — they filter a captured tab\'s own playout, not a microphone — so getUserMedia silently ignores them while the author believes self-echo is now handled at the capture layer and never writes the guard that would have handled it',
65	
66	  run(ctx) {
67	    const out = [];
68	    for (const file of ctx.files) {
69	      if (!isSource(file)) continue;
70	      const raw = ctx.read(file);
71	      if (raw === null || !DISPLAY_ONLY.some((name) => raw.includes(name))) continue;
72	      const src = stripComments(raw);
73	      const seen = new Set();
74	      CALL.lastIndex = 0;
75	      for (let m = CALL.exec(src); m; m = CALL.exec(src)) {
76	        const argsStart = m.index + m[0].length - 1;
77	        const args = balanced(src, argsStart);
78	        if (args === null) continue;
79	        for (const { start, end } of reach(src, argsStart, args)) {
80	          const region = src.slice(start, end);
81	          for (const name of DISPLAY_ONLY) {
82	            const at = region.search(new RegExp(`\\b${name}\\b`));
83	            if (at === -1) continue;
84	            const line = lineOf(src, start + at);
85	            if (seen.has(`${name}:${line}`)) continue;
86	            seen.add(`${name}:${line}`);
87	            out.push(finding(rule, {
88	              file,
89	              line,
90	              what: `a getUserMedia microphone capture asks for ${name}, which is a getDisplayMedia screen-capture constraint`,
91	              fix: `drop ${name} from the microphone constraints — it filters a captured tab's own playout out of a screen-capture track and getUserMedia ignores it outright, so it suppresses nothing here; residual self-echo has to be handled above the capture (an application-level echo guard), because the recognizer's capture takes no constraints at all`,
92	            }));
93	          }
94	        }
95	      }
96	    }
97	    return out;
98	  },
99	};
100	
101	export default rule;
102

1	// Red-first fixtures for the browser-speech pack's checks.
2	//
3	// Every rule is exercised three ways: it must FIRE on a violating source, stay
4	// QUIET on a clean one, and stay quiet on the repo's real extension/src/ tree.
5	// The third case is what makes the pack shippable — a check that only ever saw
6	// its own fixtures is a check nobody has confronted with real code.
7	//
8	// Runs in the project's own vitest (see the .claudinite/local/packs include in
9	// vitest.config.js) and imports nothing from the gitignored canon mount, so it
10	// works in CI exactly as it does locally.
11	
12	import { describe, test, expect } from 'vitest';
13	import { readdirSync, readFileSync, statSync } from 'node:fs';
14	import { join, relative, sep } from 'node:path';
15	
16	import pack from './pack.mjs';
17	import { isSource } from './lib.mjs';
18	import ttsSpeakSettles from './tts-speak-settles.mjs';
19	import sttTerminalHandlers from './stt-terminal-handlers.mjs';
20	import micCaptureReleased from './mic-capture-released.mjs';
21	import micConstraintsNotScreenCapture from './mic-constraints-not-screen-capture.mjs';
22	import sttErrorMapHasDefault from './stt-error-map-has-default.mjs';
23	
24	// A check context over a literal file map — the same {files, read} surface the
25	// engine's runner passes, with nothing else the rules are allowed to touch.
26	const ctxOf = (files) => ({
27	  files: Object.keys(files),
28	  read: (f) => (f in files ? files[f] : null),
29	});
30	
31	const run = (rule, files) => rule.run(ctxOf(files));
32	
33	describe('browser-speech pack manifest', () => {
34	  test('is a hand-declared local pack whose rules are all wired', () => {
35	    expect(pack.id).toBe('browser-speech'); // must equal the directory name
36	    expect(pack.detect).toBeNull();
37	    expect(pack.marker).toBeNull();
38	    expect(pack.prose).toBe('RULES.md');
39	    expect(pack.worldRules.map((r) => r.id).sort()).toEqual(
40	      [
41	        'mic-capture-released',
42	        'mic-constraints-not-screen-capture',
43	        'stt-error-map-has-default',
44	        'stt-terminal-handlers',
45	        'tts-speak-settles',
46	      ],
47	    );
48	  });
49	});
50	
51	// The scan must be repo-shape agnostic: a rule that only ever looks under one
52	// project's source root matches nothing — and passes vacuously green — in a repo
53	// laid out differently, which is exactly the bug these cases exist to prevent.
54	describe('source scope', () => {
55	  test('accepts browser source under any layout, in JS and TS alike', () => {
56	    for (const file of [
57	      'extension/src/speech/stt-port.js',
58	      'src/speech.ts',
59	      'app/lib/voice.tsx',
60	      'packages/web/audio.mjs',
61	      'assistant.cjs',
62	      'client/jsx/mic.jsx',
63	    ]) expect(isSource(file), file).toBe(true);
64	  });
65	
66	  test('rejects test scaffolding, fixtures and vendored code wherever they sit', () => {
67	    for (const file of [
68	      'extension-test/unit/speech-ports.test.js',
69	      'src/speech.spec.ts',
70	      'test/voice.js',
71	      '__tests__/mic.js',
72	      'src/__mocks__/recognition.js',
73	      'test/fixtures/fake-recognizer.js',
74	      'node_modules/some-pkg/speech.js',
75	      'dist/bundle.js',
76	      'README.md',
77	    ]) expect(isSource(file), file).toBe(false);
78	  });
79	});
80	
81	describe('tts-speak-settles', () => {
82	  test('fires when a chrome.tts handler only resolves on end', () => {
83	    const found = run(ttsSpeakSettles, {
84	      'extension/src/speech/bad-tts.js': `
85	        export function speak(text) {
86	          return new Promise((resolve) => {
87	            chrome.tts.speak(text, {
88	              enqueue: false,
89	              onEvent(event) {
90	                if (event.type === 'end') resolve();
91	              },
92	            });
93	          });
94	        }
95	      `,
96	    });
97	    expect(found).toHaveLength(1);
98	    expect(found[0].rule).toBe('tts-speak-settles');
99	    expect(found[0].severity).toBe('blocking');
100	    expect(found[0].what).toContain('interrupted');
101	  });
102	
103	  test('fires when a SpeechSynthesisUtterance has onend but no onerror', () => {
104	    const found = run(ttsSpeakSettles, {
105	      'extension/src/speech/bad-synth.js': `
106	        const utterance = new SpeechSynthesisUtterance(text);
107	        utterance.onend = () => resolve();
108	        synth.speak(utterance);
109	      `,
110	    });
111	    expect(found).toHaveLength(1);
112	    expect(found[0].what).toContain('error');
113	  });
114	
115	  test('fires on an utterance wired for end via addEventListener but not error', () => {
116	    const found = run(ttsSpeakSettles, {
117	      'src/voice.ts': `
118	        const utterance = new SpeechSynthesisUtterance(text);
119	        utterance.addEventListener('end', () => resolve());
120	        synth.speak(utterance);
121	      `,
122	    });
123	    expect(found).toHaveLength(1);
124	    expect(found[0].what).toContain('error');
125	  });
126	
127	  test('stays quiet on an utterance that mixes the two wiring forms', () => {
128	    // `.onend =` beside addEventListener('error') is correctly wired; a matcher
129	    // that understood only property assignment would false-alarm here.
130	    expect(run(ttsSpeakSettles, {
131	      'src/voice.ts': `
132	        const utterance = new SpeechSynthesisUtterance(text);
133	        utterance.onend = () => resolve();
134	        utterance.addEventListener('error', () => resolve());
135	      `,
136	    })).toEqual([]);
137	  });
138	
139	  test('stays quiet on a handler that delegates to a hoisted terminal set', () => {
140	    // It enumerates nothing inline, so the rule cannot read it — and says
141	    // nothing rather than guessing. This code is correct; firing would be noise.
142	    expect(run(ttsSpeakSettles, {
143	      'src/tts.js': `
144	        const TERMINAL = new Set(['end', 'interrupted', 'cancelled', 'error']);
145	        function isDone(type) { return TERMINAL.has(type); }
146	        chrome.tts.speak(text, {
147	          onEvent(event) { if (isDone(event.type)) resolve(); },
148	        });
149	      `,
150	    })).toEqual([]);
151	  });
152	
153	  test('stays quiet on a handler that covers every terminal event', () => {
154	    expect(run(ttsSpeakSettles, {
155	      'extension/src/speech/good-tts.js': `
156	        chrome.tts.speak(text, {
157	          enqueue: false,
158	          onEvent(event) {
159	            if (['end', 'interrupted', 'cancelled', 'error'].includes(event.type)) resolve();
160	          },
161	        });
162	        const utterance = new SpeechSynthesisUtterance(text);
163	        utterance.onend = () => resolve();
164	        utterance.onerror = () => resolve();
165	      `,
166	    })).toEqual([]);
167	  });
168	
169	  test('stays quiet on a speak() call that supplies no onEvent handler', () => {
170	    // The orchestrator's own tts.speak(text, {rate}) goes through the port, which
171	    // already owns the terminal handling — holding it to this rule would be noise.
172	    expect(run(ttsSpeakSettles, {
173	      'extension/src/app/orchestrator.js': "await tts.speak(phrases.render(a.say), { rate });",
174	    })).toEqual([]);
175	  });
176	
177	  test('stays quiet when the only mention of the trap is a comment', () => {
178	    expect(run(ttsSpeakSettles, {
179	      'extension/src/speech/note.js': `
180	        // chrome.tts.speak(text, { onEvent(e) { if (e.type === 'end') resolve(); } })
181	        export const NOTE = 1;
182	      `,
183	    })).toEqual([]);
184	  });
185	});
186	
187	describe('stt-terminal-handlers', () => {
188	  test('fires on a recognizer wired for onresult alone', () => {
189	    const found = run(sttTerminalHandlers, {
190	      'extension/src/speech/bad-stt.js': `
191	        const rec = new Recognition();
192	        rec.onresult = (event) => resolve(event.results);
193	        rec.start();
194	      `,
195	    });
196	    expect(found).toHaveLength(1);
197	    expect(found[0].what).toContain('end');
198	    expect(found[0].what).toContain('error');
199	  });
200	
201	  test('fires when only onend is missing', () => {
202	    const found = run(sttTerminalHandlers, {
203	      'extension/src/speech/half-stt.js': `
204	        rec.onresult = (event) => settle(event);
205	        rec.onerror = (event) => settle({ error: event.error });
206	      `,
207	    });
208	    expect(found).toHaveLength(1);
209	    expect(found[0].what).toContain('end');
210	    expect(found[0].what).not.toContain('error');
211	  });
212	
213	  test('stays quiet when all three handlers are wired', () => {
214	    expect(run(sttTerminalHandlers, {
215	      'extension/src/speech/good-stt.js': `
216	        rec.onresult = (event) => settle(event);
217	        rec.onerror = (event) => settle({ error: mapSttError(event?.error) });
218	        rec.onend = () => settle({ error: 'no-speech' });
219	      `,
220	    })).toEqual([]);
221	  });
222	
223	  test('fires on an addEventListener-wired recognizer missing end', () => {
224	    // The rule used to hinge entirely on `.onresult =`, so a recognizer wired
225	    // the other legal way was not judged at all — it passed silently.
226	    const found = run(sttTerminalHandlers, {
227	      'src/listen.ts': `
228	        const rec = new webkitSpeechRecognition();
229	        rec.addEventListener('result', (event) => settle(event));
230	        rec.addEventListener('error', (event) => settle({ error: event.error }));
231	        rec.start();
232	      `,
233	    });
234	    expect(found).toHaveLength(1);
235	    expect(found[0].what).toContain('end');
236	  });
237	
238	  test('stays quiet on a recognizer that mixes the two wiring forms', () => {
239	    expect(run(sttTerminalHandlers, {
240	      'src/listen.ts': `
241	        rec.onresult = (event) => settle(event);
242	        rec.addEventListener('error', (event) => settle({ error: event.error }));
243	        rec.addEventListener('end', () => settle({ error: 'no-speech' }));
244	      `,
245	    })).toEqual([]);
246	  });
247	});
248	
249	describe('mic-capture-released', () => {
250	  test('fires on a capture that is never released', () => {
251	    const found = run(micCaptureReleased, {
252	      'extension/src/speech/bad-mic.js': `
253	        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
254	        return { status: 'granted' };
255	      `,
256	    });
257	    expect(found).toHaveLength(1);
258	    expect(found[0].fix).toContain('finally');
259	  });
260	
261	  test('stays quiet when the tracks are stopped', () => {
262	    expect(run(micCaptureReleased, {
263	      'extension/src/speech/good-mic.js': `
264	        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
265	        try {
266	          return { status: 'granted' };
267	        } finally {
268	          stream.getTracks().forEach((t) => t.stop());
269	        }
270	      `,
271	    })).toEqual([]);
